/* ---------- matching (validado em teste isolado) ---------- */
const STOP = new Set(("a o as os de da do das dos e ou que um uma no na nos nas em para por com sem foi era esta este isso muito mais menos ja nao sim se ao aos pra pro durante quando qual quais como onde tem ter fazer feito coisa coisas ficou ficaram varias varios meio final depois causa disso entre").split(/\s+/));
const SYN = {
  requisito:"requisito",requisitos:"requisito",pbi:"requisito",pbis:"requisito",historia:"requisito",historias:"requisito",escopo:"requisito",spec:"requisito",especificacao:"requisito",regra:"requisito",card:"requisito",
  mudou:"mudanca",mudanca:"mudanca",mudancas:"mudanca",mudaram:"mudanca",alterou:"mudanca",alterado:"mudanca",alteracao:"mudanca",instavel:"mudanca",instabilidade:"mudanca",trocou:"mudanca",
  comunicacao:"comunicacao",comunicar:"comunicacao",alinhamento:"comunicacao",alinhar:"comunicacao",ruido:"comunicacao",
  retrabalho:"retrabalho",refazer:"retrabalho",refeito:"retrabalho",
  teste:"teste",testes:"teste",qa:"teste",bug:"teste",bugs:"teste",qualidade:"teste",
  prazo:"prazo",atraso:"prazo",atrasou:"prazo",atrasada:"prazo",atrasado:"prazo",deadline:"prazo",tempo:"prazo",
  estimativa:"estimativa",estimativas:"estimativa",estimar:"estimativa",
  clareza:"clareza",claro:"clareza",clara:"clareza",incompleto:"clareza",incompletos:"clareza",vago:"clareza",vagos:"clareza",indefinido:"clareza",fechado:"clareza",
  refinamento:"refinamento",refinar:"refinamento",grooming:"refinamento",detalhamento:"refinamento",
  daily:"daily",planning:"planning",dependencia:"dependencia",externa:"dependencia",bloqueio:"dependencia",
  priorizacao:"priorizacao",prioridade:"priorizacao",priorizar:"priorizacao",
  documentacao:"documentacao",doc:"documentacao",documentar:"documentacao",
  planejamento:"planejamento",planejar:"planejamento",
};
const norm = s => s.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/[^a-z0-9\s]/g," ").split(/\s+/).filter(Boolean);
function sig(text){
  const toks=new Map(), concepts=new Set();
  for(const w of norm(text)){
    if(STOP.has(w)||w.length<3) continue;
    if(SYN[w]){const c=SYN[w];concepts.add(c);toks.set(c,4);}
    else if(!toks.has(w)) toks.set(w,1);
  }
  return {toks,concepts};
}
function simil(a,b){
  let inter=0,uni=0; const keys=new Set([...a.toks.keys(),...b.toks.keys()]);
  for(const k of keys){const wa=a.toks.get(k)||0,wb=b.toks.get(k)||0;inter+=Math.min(wa,wb);uni+=Math.max(wa,wb);}
  let score=uni?inter/uni:0;
  const shared=[...a.concepts].filter(c=>b.concepts.has(c)).length;
  const denom=new Set([...a.concepts,...b.concepts]).size||1;
  return 0.5*score+0.5*(shared/denom);
}
// answers: [{by, text}] -> clusters ordenados por tamanho
function clusterize(answers, threshold=0.4){
  const clusters=[];
  for(const ans of answers){
    if(!ans.text||!ans.text.trim()) continue;
    const s=sig(ans.text); if(!s.toks.size) continue;
    let best=null,bs=0;
    for(const c of clusters){const sc=simil(s,c.sig); if(sc>bs){bs=sc;best=c;}}
    if(best&&bs>=threshold){
      best.members.push(ans);
      for(const [k,w] of s.toks) best.sig.toks.set(k,Math.max(best.sig.toks.get(k)||0,w));
      for(const c of s.concepts) best.sig.concepts.add(c);
    } else clusters.push({sig:{toks:new Map(s.toks),concepts:new Set(s.concepts)},members:[ans]});
  }
  return clusters.sort((a,b)=>b.members.length-a.members.length);
}
// rótulo legível: prioriza uma resposta que a pessoa DECLAROU como crime (weight),
// senão a resposta representativa mais curta.
function labelOf(cluster){
  const declared=cluster.members.filter(m=>m.weight);
  const pool=declared.length?declared:cluster.members;
  const byLen=[...pool].sort((a,b)=>a.text.length-b.text.length);
  return byLen[0].text.trim();
}
// conceitos que são SINTOMA (consequência), não causa-raiz do crime.
const SYMPTOM=new Set(["retrabalho","prazo"]);
// pontuação de "quão crime" é um cluster: nº de pessoas + bônus por declaração
// explícita, penalidade se o cluster é puramente sintoma.
function crimeScore(c,total){
  let s=c.count;
  if(c.declaredBy) s+=c.declaredBy*0.9;           // apareceu como crime declarado
  const onlySymptom=c.concepts.length>0 && c.concepts.every(x=>SYMPTOM.has(x));
  if(onlySymptom) s*=0.45;                          // retrabalho é efeito, não crime
  return s;
}
function strength(count,total){
  const p=total? count/total:0;
  // P&B: forte usa o acento (vermelho), demais usam tinta; 'accent' liga a hachura vermelha
  if(p>=0.8) return {level:"forte",color:"var(--accent)",accent:true,pct:Math.round(p*100)};
  if(p>=0.5) return {level:"moderada",color:"var(--ink)",accent:false,pct:Math.round(p*100)};
  return {level:"fraca",color:"var(--ink-soft)",accent:false,pct:Math.round(p*100)};
}

/* ---------- sala compartilhada (Supabase) ----------
   readRoom, writeRoom, upsertPlayer, subscribeRoom, genCode, uid
   vêm do serviço em ./services/rooms.js (importado no topo). */

/* ============================================================
   COMPONENTE PRINCIPAL
   ============================================================ */
export default function DetetiveDaSprint(){
  const [screen,setScreen]=useState("home"); // home | persona | invest | wait | result
  const [code,setCode]=useState("");
  const [sprint,setSprint]=useState("");
  const [me,setMe]=useState(null);       // meu jogador (objeto completo)
  const [room,setRoom]=useState(null);   // estado da sala (polling)
  const [err,setErr]=useState("");

  // sincronização da sala em tempo real (Supabase Realtime)
  useEffect(()=>{
    if(!code || screen==="home" || screen==="persona") return;
    let alive=true;
    // leitura inicial imediata
    (async()=>{ const r=await readRoom(code); if(alive&&r) setRoom(r); })();
    // assina mudanças: qualquer jogador que fecha o dossiê atualiza todos na hora
    const unsub=subscribeRoom(code,(r)=>{ if(alive&&r) setRoom(r); });
    return ()=>{ alive=false; unsub(); };
  },[code,screen]);

  return (
    <div className={"dds"+(screen==="result"?" neg":"")}>
      <style>{CSS}</style>
      <div className="wrap">
        {screen==="home" &&
          <Home
            onCreate={async(sp)=>{
              const c=genCode();
              const ok=await writeRoom(c,{code:c,sprint:sp,phase:"open",createdAt:Date.now(),updatedAt:Date.now(),players:[]});
              if(!ok){setErr("Não consegui abrir a sala. Tente de novo.");return;}
              setCode(c);setSprint(sp);setScreen("persona");
            }}
            onJoin={async(c)=>{
              const r=await readRoom(c.toUpperCase());
              if(!r){setErr(`Nenhum caso encontrado com o código ${c.toUpperCase()}.`);return;}
              setErr("");setCode(r.code);setSprint(r.sprint);setRoom(r);setScreen("persona");
            }}
            err={err}
          />}

        {screen==="persona" &&
          <Persona
            code={code} sprint={sprint}
            onReady={async(persona)=>{
              const player={...persona,id:uid(),done:false,answers:emptyAnswers()};
              const r=await upsertPlayer(code,player);
              setMe(player); if(r) setRoom(r); setScreen("invest");
            }}
          />}

        {screen==="invest" &&
          <Investigacao
            code={code} sprint={sprint} me={me}
            onSave={async(answers)=>{ const p={...me,answers}; setMe(p); await upsertPlayer(code,p); }}
            onFinish={async(answers)=>{
              const p={...me,answers,done:true}; setMe(p);
              const r=await upsertPlayer(code,p); if(r) setRoom(r); setScreen("wait");
            }}
          />}

        {screen==="wait" &&
          <SalaEspera
            code={code} sprint={sprint} room={room} me={me}
            onReveal={async()=>{
              const r=await readRoom(code); if(r){r.phase="closed";await writeRoom(code,r);setRoom(r);}
              setScreen("result");
            }}
          />}

        {screen==="result" &&
          <Resultado code={code} sprint={sprint} room={room}
            onNew={()=>{setScreen("home");setCode("");setMe(null);setRoom(null);setSprint("");}}/>}
      </div>
    </div>
  );
}

function emptyAnswers(){
  return {
    crime:"", ferramentas:[], ferramentasExtra:"",
    pistas:{p1:"",p2:"",p3:"",p4:"",p5:""},
    suspeitos:[], alibis:{}, atencao:"", acao:"",
    votos:{crime:"",atencao:"",continuar:"",acao:""},
  };
}

